"""Food system with different types and effects."""

import random
import pygame
from config import (COLORS, GRID_SIZE, COLS, ROWS, FOOD_NORMAL, 
                    FOOD_COMBO, FOOD_SPEED, SPECIAL_FOOD_SPAWN_RATE)


class Food:
    """Represents food on the grid with visual effects."""

    def __init__(self, x, y, food_type=FOOD_NORMAL):
        self.x = x  # Grid coordinates
        self.y = y
        self.food_type = food_type

        # Animation properties
        self.blink_phase = random.uniform(0, 6.28)
        self.grow_scale = 1.0
        self.target_scale = 1.0

        # Combo timer
        self.combo_timer = None

    def get_screen_position(self):
        """Convert grid position to screen coordinates."""
        return (self.x * GRID_SIZE + GRID_SIZE // 2, 
                self.y * GRID_SIZE + GRID_SIZE // 2)

    def update_glow(self, delta_time):
        """Update glow animation based on food type."""
        self.blink_phase += delta_time * 0.15

        if self.food_type == FOOD_COMBO:
            # Pulsate more for combo food
            self.grow_scale = 1.0 + 0.2 * abs(pygame.math.Vector2(0, 0).length())
            self.target_scale = 1.3

        elif self.food_type == FOOD_SPEED:
            # Spin effect indicator through color cycling
            pass

    def get_color(self):
        """Get the appropriate color for this food type."""
        if self.food_type == FOOD_COMBO:
            return (COLORS['food_combo'], COLORS['food_combo_glow'])
        elif self.food_type == FOOD_SPEED:
            return (COLORS['food_speed'], COLORS['food_speed_glow'])
        else:
            return (COLORS['food_normal'], COLORS['food_glow'])

    def draw(self, surface):
        """Draw the food with glow effects."""
        center = self.get_screen_position()

        # Calculate blink effect
        blink_factor = abs(pygame.math.Vector2(0, 0).length()) if hasattr(pygame.math.Vector2, 'length') else abs((self.blink_phase % 6.28) / 3.14 - 1)

        colors = self.get_color()
        base_color = colors[0]
        glow_color = colors[1]

        # Dynamic scale based on blink phase
        dynamic_scale = 1.0 + 0.15 * abs((self.blink_phase % 6.28) / 3.14 - 1)

        # Draw outer glow (larger, transparent)
        glow_radius = int(GRID_SIZE // 2 * dynamic_scale * 1.3)
        for i in range(5):
            radius = glow_radius - i * (glow_radius // 5)
            alpha_factor = max(0, 1 - i / 4)
            # Create gradient glow effect
            r, g, b = glow_color[0] + int((255 - glow_color[0]) * alpha_factor), \
                     glow_color[1] + int((255 - glow_color[1]) * alpha_factor), \
                     glow_color[2] + int((255 - glow_color[2]) * alpha_factor)
            color = (r, g, b)

            # Draw a slightly larger circle for each layer
            try:
                pygame.draw.circle(surface, color, center, radius)
            except:
                pass

        # Draw inner glow
        inner_radius = int(GRID_SIZE // 2 * dynamic_scale * 1.1)
        try:
            pygame.draw.circle(surface, glow_color, center, inner_radius)
        except:
            pass

        # Draw main food (core)
        core_radius = int(GRID_SIZE // 2 * dynamic_scale * 0.85)
        try:
            pygame.draw.circle(surface, base_color, center, core_radius)

            # Add shine/highlight for 3D effect
            highlight_x = center[0] - int(core_radius * 0.3)
            highlight_y = center[1] - int(core_radius * 0.3)
            highlight_radius = int(core_radius * 0.35)
            pygame.draw.circle(surface, (255, 255, 255), 
                             (highlight_x, highlight_y), highlight_radius)

        except:
            pass

        # Draw special indicators for special foods
        if self.food_type == FOOD_COMBO:
            # Draw "x" indicator or combo marker
            try:
                pygame.draw.line(surface, COLORS['text_primary'], 
                               (center[0] - 5, center[1] - 8), 
                               (center[0] + 5, center[1] + 8), 2)
                pygame.draw.line(surface, COLORS['text_primary'], 
                               (center[0] + 5, center[1] - 8), 
                               (center[0] - 5, center[1] + 8), 2)
            except:
                pass

        elif self.food_type == FOOD_SPEED:
            # Draw lightning bolt or speed indicator
            try:
                points = [
                    (center[0], center[1] - int(core_radius * 0.7)),
                    (center[0] + int(core_radius * 0.3), center[1]),
                    (center[0], center[1] - int(core_radius * 0.3)),
                    (center[0] + int(core_radius * 0.5), center[1] + int(core_radius * 0.4)),
                    (center[0], center[1] + int(core_radius * 0.2)),
                    (center[0] - int(core_radius * 0.3), center[1]),
                ]
                pygame.draw.polygon(surface, COLORS['text_primary'], points)
            except:
                pass


class FoodManager:
    """Manages food spawning and removal."""

    def __init__(self):
        self.current_food = None
        self.combo_timer = 0
        self.last_food_time = pygame.time.get_ticks() / 1000.0

    def spawn_food(self, snake_body=None, avoid_positions=set()):
        """Spawn food at a random location not occupied by the snake."""

        # Determine food type based on game state
        time_since_last = (pygame.time.get_ticks() / 1000.0) - self.last_food_time

        if snake_body and len(snake_body) > 5:
            # Higher chance for special foods as game progresses
            rand_val = random.random()

            if rand_val < SPECIAL_FOOD_SPAWN_RATE:
                food_type = FOOD_SPEED
            elif time_since_last < COMBO_THRESHOLD and self.combo_timer > 0:
                food_type = FOOD_COMBO
            else:
                food_type = FOOD_NORMAL
        else:
            # Early game - mostly normal food
            if random.random() < 0.1:
                food_type = FOOD_SPEED
            else:
                food_type = FOOD_NORMAL

        # Find a valid position
        max_attempts = 100
        for _ in range(max_attempts):
            x = random.randint(0, COLS - 1)
            y = random.randint(0, ROWS - 1)

            pos_key = (x, y)
            if pos_key not in avoid_positions:
                # Also check against snake body
                is_occupied = False
                if snake_body:
                    for segment in snake_body:
                        if segment['x'] == x and segment['y'] == y:
                            is_occupied = True
                            break

                if not is_occupied:
                    self.current_food = Food(x, y, food_type)
                    self.last_food_time = pygame.time.get_ticks() / 1000.0

                    # Start combo timer if we just ate something recently
                    if time_since_last < COMBO_THRESHOLD and food_type != FOOD_SPEED:
                        self.combo_timer = int(time_since_last * 10)  # Store as integer
                    else:
                        self.combo_timer = 0

                    return

        # If no valid position found, try to find any empty cell
        for y in range(ROWS):
            for x in range(COLS):
                pos_key = (x, y)
                if pos_key not in avoid_positions:
                    is_occupied = False
                    if snake_body:
                        for segment in snake_body:
                            if segment['x'] == x and segment['y'] == y:
                                is_occupied = True
                                break

                    if not is_occupied:
                        self.current_food = Food(x, y, food_type)
                        self.last_food_time = pygame.time.get_ticks() / 1000.0
                        return

    def get_current_food(self):
        """Get the current active food."""
        return self.current_food

    def remove_food(self):
        """Remove the current food after being eaten."""
        self.current_food = None

    def update_combo_timer(self, delta_time):
        """Update combo timer based on time since last food."""
        if self.current_food is not None:
            self.combo_timer -= delta_time

    def get_effective_type(self):
        """Get the effective food type considering combo state."""
        if self.current_food and self.combo_timer > 0:
            return FOOD_COMBO
        return self.current_food.food_type if self.current_food else None

